const addIsoMonths=(month:string,count:number)=>{const [y,m]=month.split('-').map(Number);const d=new Date(Date.UTC(y,m-1+count,1));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`};
const previousMonth=(month:string)=>addIsoMonths(month,-1);
const monthOptions=Array.from({length:25},(_,i)=>{const d=new Date(Date.UTC(2026,7+i,1));return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`});
const csvCell=(value:string)=>`"${value.replace(/"/g,'""')}"`;
const csvFile=(headers:string[],rows:(string|number|null)[][])=>[headers,...rows].map(row=>row.map(value=>csvCell(value===null?'':String(value))).join(',')).join('\n');
const assumptionCsv=(value:Record<string,unknown>)=>[['field','value'],...Object.entries(value).map(([key,item])=>[key,JSON.stringify(item)])].map(row=>row.map(csvCell).join(',')).join('\n');
const parseAssumptionCsv=(text:string)=>{const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted&&ch==='"'&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"'){quoted=!quoted}else if(ch===','&&!quoted){row.push(cell);cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=ch}row.push(cell);if(row.some(Boolean))rows.push(row);if(rows[0]?.[0]!=='field'||rows[0]?.[1]!=='value')throw new Error('Unsupported assumptions CSV');return Object.fromEntries(rows.slice(1).map(([key,value])=>[key,JSON.parse(value)]))};
const defaults: Assumptions = { months:12, monthlyTrafficGrowth:.03, signupRate:.137, purchaseRate:.008, voluntaryCustomerChurn:.045, delinquentCustomerChurn:.012, voluntaryRevenueChurn:.045, delinquentRevenueChurn:.012, expansionRate:.018, retractionRate:.006, newCustomerArpu:38, grossMargin:.85, targetLtvCac:3, monthlyIncrementalVisitors:0, monthlySalesMarketingOverhead:0 };
const scenarios: Record<string,Partial<Assumptions>> = { Conservative:{monthlyTrafficGrowth:0,signupRate:.11,purchaseRate:.005}, Baseline:{monthlyTrafficGrowth:.03,signupRate:.137,purchaseRate:.008}, Ambitious:{monthlyTrafficGrowth:.08,signupRate:.17,purchaseRate:.012} };
