type SavedModel={modelName:string;baseline:{month:string;visitors:number;signups:number;newCustomers:number;customers:number;mrr:number;arpu:number;arr:number};forecastStartMonth:string;assumptions:Assumptions;channelDefaults:{signupRate:number;purchaseRate:number;arpu:number};scenario:string;budget:number;channels:EditableChannel[];monthlyBudgetGrowth:number;monthlyBudgetOverrides:Record<string,Record<string,number>>;monthlyChurnOverrides:Record<string,number>;cashFlowSettings:CashFlowSettings};
const storageKey='growth-model-state-v1';
const loadSavedModel=():Partial<SavedModel>=>{try{return validateSavedModel(JSON.parse(localStorage.getItem(storageKey)||'{}'))}catch{return {}}};
const normalizeChannels=(channels?:EditableChannel[])=>{const defaults=initialChannels();if(!channels?.length)return defaults;const byName=new Map(channels.map(c=>[c.name,c]));const merged=defaults.map(base=>{const saved=byName.get(base.name);return saved?{...base,...saved,affiliateCommissionRate:saved.affiliateCommissionRate??base.affiliateCommissionRate,affiliateCommissionMonths:saved.affiliateCommissionMonths??base.affiliateCommissionMonths}:base});const known=new Set(defaults.map(c=>c.name));return [...merged,...channels.filter(c=>!known.has(c.name))]};
const finiteNonnegative=(value:unknown)=>typeof value==='number'&&Number.isFinite(value)&&value>=0;
function validateSavedModel(input:unknown):Partial<SavedModel>{if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Model state must be an object');const value=input as Partial<SavedModel>;if(value.budget!==undefined&&!finiteNonnegative(value.budget))throw new Error('Invalid budget');if(value.monthlyBudgetGrowth!==undefined&&!finiteNonnegative(value.monthlyBudgetGrowth))throw new Error('Invalid budget growth');if(value.modelName!==undefined&&typeof value.modelName!=='string')throw new Error('Invalid model name');if(value.forecastStartMonth!==undefined&&!/^\d{4}-\d{2}$/.test(value.forecastStartMonth))throw new Error('Invalid forecast month');const result:{[key:string]:unknown}={...value};if(value.baseline){if(!/^\d{4}-\d{2}$/.test(value.baseline.month)||[value.baseline.visitors,value.baseline.signups,value.baseline.newCustomers,value.baseline.customers,value.baseline.mrr].some(v=>!finiteNonnegative(v)))throw new Error('Invalid baseline');result.baseline={...value.baseline,arpu:value.baseline.customers?value.baseline.mrr/value.baseline.customers:0,arr:value.baseline.mrr*12}}if(value.assumptions){const assumptions={...defaults,...value.assumptions};const rates:(keyof Assumptions)[]= ['signupRate','purchaseRate','voluntaryCustomerChurn','delinquentCustomerChurn','voluntaryRevenueChurn','delinquentRevenueChurn','expansionRate','retractionRate','grossMargin'];if(!Number.isInteger(assumptions.months)||assumptions.months<1||assumptions.months>60||rates.some(key=>!finiteNonnegative(assumptions[key])||assumptions[key]>1)||!finiteNonnegative(assumptions.monthlyTrafficGrowth)||!finiteNonnegative(assumptions.newCustomerArpu)||!finiteNonnegative(assumptions.monthlySalesMarketingOverhead)||!Number.isFinite(assumptions.targetLtvCac)||assumptions.targetLtvCac<=0)throw new Error('Invalid assumptions');result.assumptions=assumptions}if(value.channels){if(!Array.isArray(value.channels)||new Set(value.channels.map(c=>c.name)).size!==value.channels.length||value.channels.some(c=>!c.name||!['manual','cpc','cpm'].includes(c.model)||!Number.isInteger(c.goLiveMonth)||c.goLiveMonth<0||[c.visitors,c.signupRate,c.purchaseRate,c.arpu,c.allocation,c.cpc,c.cpm,c.ctr,c.affiliateCommissionRate??0,c.affiliateCommissionMonths??0].some(v=>!finiteNonnegative(v))||c.signupRate>1||c.purchaseRate>1||c.allocation>1||c.ctr>1))throw new Error('Invalid channels');result.channels=normalizeChannels(value.channels)}const validMap=(map:unknown,max=Infinity)=>{if(!map||typeof map!=='object'||Array.isArray(map))return false;return Object.values(map as Record<string,unknown>).every(v=>finiteNonnegative(v)&&Number(v)<=max)};if(value.monthlyBudgetOverrides){if(!Object.values(value.monthlyBudgetOverrides).every(v=>validMap(v)))throw new Error('Invalid budget overrides')}if(value.monthlyChurnOverrides&&!validMap(value.monthlyChurnOverrides,1))throw new Error('Invalid churn overrides');if(value.cashFlowSettings){const cash={...defaultCashFlow,...value.cashFlowSettings};const shares=cash.monthlyShare+cash.annualShare+(cash.oneTimeEnabled?cash.oneTimeShare:0);if([cash.feeRate,cash.refundRate,cash.monthlyShare,cash.annualShare,cash.oneTimeShare].some(v=>!finiteNonnegative(v)||v>1)||typeof cash.oneTimeEnabled!=='boolean'||Math.abs(shares-1)>.001)throw new Error('Invalid cash-flow settings');result.cashFlowSettings=cash}return result as Partial<SavedModel>}

type NumericKey = keyof Assumptions;
const fields: {key:NumericKey; label:string; step:number; kind:'pct'|'number'|'money'; hint:string}[] = [
 {key:'months',label:'Forecast range',step:1,kind:'number',hint:'Months ahead'}, {key:'monthlyTrafficGrowth',label:'Traffic growth',step:.005,kind:'pct',hint:'Monthly'},
 {key:'signupRate',label:'Visitor → signup',step:.005,kind:'pct',hint:'Observed baseline'}, {key:'purchaseRate',label:'Signup → purchase',step:.01,kind:'pct',hint:'Paid conversion'},
 {key:'voluntaryCustomerChurn',label:'Voluntary logo churn',step:.005,kind:'pct',hint:'Monthly'}, {key:'delinquentCustomerChurn',label:'Delinquent logo churn',step:.0025,kind:'pct',hint:'Monthly'},
 {key:'voluntaryRevenueChurn',label:'Voluntary revenue churn',step:.005,kind:'pct',hint:'Monthly'}, {key:'delinquentRevenueChurn',label:'Delinquent revenue churn',step:.0025,kind:'pct',hint:'Monthly'},
 {key:'expansionRate',label:'Expansion rate',step:.0025,kind:'pct',hint:'Existing MRR'}, {key:'retractionRate',label:'Downgrade rate',step:.0025,kind:'pct',hint:'Existing MRR'},
 {key:'newCustomerArpu',label:'New customer ARPU',step:1,kind:'money',hint:'Monthly'}, {key:'grossMargin',label:'Gross margin',step:.01,kind:'pct',hint:'Contribution LTV'},
 {key:'targetLtvCac',label:'Target LTV:CAC',step:.25,kind:'number',hint:'Efficiency target'}, {key:'monthlySalesMarketingOverhead',label:'Sales & Marketing Overhead',step:100,kind:'money',hint:'Monthly salaries, commissions, and tools'}
];
function Field({f,a,setA}:{f:typeof fields[number];a:Assumptions;setA:(a:Assumptions)=>void}) { const display=one(f.kind==='pct'?a[f.key]*100:a[f.key]); return <label className="field"><span>{f.label}<small>{f.hint}</small></span><div className="input"><input aria-label={f.label} type="number" min={f.key==='months'?1:0} max={f.key==='months'?60:f.kind==='pct'?100:undefined} step={f.kind==='pct'?f.step*100:f.step} value={display} onChange={e=>{const raw=+e.target.value;setA({...a,[f.key]:f.key==='months'?Math.max(1,Math.min(60,Math.round(raw))):f.kind==='pct'?raw/100:raw})}}/><b>{f.kind==='pct'?'%':f.kind==='money'?'$':''}</b></div></label> }
function ChannelRow({channel:c,modeled,index,budget,setChannels,channels}:{channel:EditableChannel;modeled:EditableChannel;index:number;budget:number;setChannels:(c:EditableChannel[])=>void;channels:EditableChannel[]}){
 const update=(patch:Partial<EditableChannel>)=>setChannels(channels.map((x,i)=>i===index?{...x,...patch}:x)); const setLiveMonth=(goLiveMonth:number)=>{if(goLiveMonth!==0||c.goLiveMonth===0||c.model==='manual'||c.allocation===0){update({goLiveMonth});return}const recipients=channels.map((x,i)=>({x,i})).filter(({x,i})=>i!==index&&x.model!=='manual'&&x.goLiveMonth>0);const weight=recipients.reduce((sum,{x})=>sum+x.allocation,0);setChannels(channels.map((x,i)=>{if(i===index)return {...x,goLiveMonth:0,allocation:0};const recipient=recipients.find(r=>r.i===i);if(!recipient)return x;const share=weight?x.allocation/weight:1/recipients.length;return {...x,allocation:x.allocation+c.allocation*share}}))}; const spend=c.goLiveMonth===0?0:budget*c.allocation; const impliedCpc=modeled.visitors?spend/modeled.visitors:0;
 return <details className="channel"><summary><strong>{c.name}</strong><label>Live month<input aria-label={`${c.name} goLiveMonth`} type="number" min="0" max="60" step="1" value={c.goLiveMonth} onChange={e=>setLiveMonth(+e.target.value)}/></label>{c.model==='manual'?<label>Launch visitors<input aria-label={`${c.name} visitors`} type="number" min="0" step="100" value={one(c.visitors)} onChange={e=>update({visitors:+e.target.value})}/></label>:<><label>Budget %<input aria-label={`${c.name} allocation`} type="number" min="0" max="100" step="1" value={one(c.allocation*100)} onChange={e=>update({allocation:+e.target.value/100})}/><small>{money(spend)}</small></label>{c.model==='cpc'?<label>CPC<input aria-label={`${c.name} cpc`} type="number" min="0" step=".1" value={one(c.cpc)} onChange={e=>update({cpc:+e.target.value})}/></label>:<><label>CPM<input aria-label={`${c.name} cpm`} type="number" min="0" step=".1" value={one(c.cpm)} onChange={e=>update({cpm:+e.target.value})}/></label><label>CTR %<input aria-label={`${c.name} ctr`} type="number" min="0" step=".1" value={one(c.ctr*100)} onChange={e=>update({ctr:+e.target.value/100})}/></label></>}</>}<span className="traffic"><b>{number(modeled.visitors)}</b> visits<small>{c.model!=='manual'?`${money(impliedCpc)} expected CPC`:''}</small></span></summary><div className="channelAdvanced"><label>Visitor → signup %<input aria-label={`${c.name} signupRate`} type="number" min="0" step=".1" value={one(c.signupRate*100)} onChange={e=>update({signupRate:+e.target.value/100})}/></label><label>Signup → purchase %<input aria-label={`${c.name} purchaseRate`} type="number" min="0" step=".1" value={one(c.purchaseRate*100)} onChange={e=>update({purchaseRate:+e.target.value/100})}/></label><label>New customer ARPU<input aria-label={`${c.name} arpu`} type="number" min="0" step=".1" value={one(c.arpu)} onChange={e=>update({arpu:+e.target.value})}/></label>{c.name==='Partners'&&<><label>Affiliate commission %<input aria-label="Partners affiliate commission rate" type="number" min="0" max="100" step=".1" value={one((c.affiliateCommissionRate||0)*100)} onChange={e=>update({affiliateCommissionRate:+e.target.value/100})}/></label><label>Commission months<input aria-label="Partners affiliate commission months" type="number" min="0" step="1" value={c.affiliateCommissionMonths||0} onChange={e=>update({affiliateCommissionMonths:+e.target.value})}/></label><div className="affiliateSummary"><span>Maximum commission / customer</span><b>{money(c.arpu*(c.affiliateCommissionRate||0)*(c.affiliateCommissionMonths||0))}</b><small>Before modeled revenue churn</small></div></>}<button className="hideChannel" onClick={()=>update({hidden:!c.hidden})}>{c.hidden?'Restore subchannel':'Hide subchannel'}</button></div></details>
}
