async function renderChartCanvas(element:HTMLElement){return toCanvas(element,{backgroundColor:'#ffffff',pixelRatio:2,cacheBust:true,skipFonts:false})}
async function exportElementImage(targetId:string,filename:string,title:string,description:string,square=false){const element=document.getElementById(targetId);if(!element)return;await document.fonts.ready;await new Promise(resolve=>setTimeout(resolve,900));const width=square?1200:1230,height=square?1200:600;const stage=document.createElement('section');stage.className=`exportStage ${square?'exportStageSquare':''}`;stage.style.width=`${width}px`;stage.style.height=`${height}px`;const heading=document.createElement('header');heading.innerHTML=`<div><span>GROWTHCAST FORECAST</span><h2>${title}</h2><p>${description}</p></div>`;const body=document.createElement('div');body.className='exportStageBody';if(square){const clone=element.cloneNode(true) as HTMLElement;clone.removeAttribute('id');body.appendChild(clone)}else{const chartCanvas=await renderChartCanvas(element);const image=document.createElement('img');image.className='exportChartImage';image.src=chartCanvas.toDataURL('image/png');body.appendChild(image)}stage.append(heading,body);document.body.appendChild(stage);try{await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));const canvas=await html2canvas(stage,{backgroundColor:'#f4f1e9',width,height,scale:1,useCORS:true,logging:false});const link=document.createElement('a');link.href=canvas.toDataURL('image/png');link.download=filename;link.click()}finally{stage.remove()}}
function ImageExportButton({targetId,filename,title,description,square=false}:{targetId:string;filename:string;title:string;description:string;square?:boolean}){const [status,setStatus]=useState('');const [busy,setBusy]=useState(false);return <><button type="button" className="imageExport" aria-label={`Export ${filename} image`} title="Export image" disabled={busy} onClick={async()=>{setBusy(true);setStatus('');try{await exportElementImage(targetId,filename,title,description,square);setStatus(`${filename} downloaded`)}catch{setStatus(`Could not export ${filename}`)}finally{setBusy(false)}}}><ImageDown size={15}/></button><span className="srOnly" aria-live="polite">{status}</span></>}
